function checkWindowSize(n) {
	if (!Number.isInteger(n) || n < 1) {
		throw new RangeError(`windowSize must be an integer of 1 or more, got ${n}`);
	}
}

export class RollingMedian {
	/** @param {number} windowSize */
	constructor(windowSize) {
		checkWindowSize(windowSize);
		/** @type {number} */
		this.windowSize = windowSize;
		/** @type {number[]} */
		this.window = [];
	}

	/** @param {number} x @returns {number} */
	add(x) {
		if (typeof x !== "number" || !Number.isFinite(x)) {
			throw new TypeError(`x must be a finite number, got ${x}`);
		}
		this.window.push(x);
		if (this.window.length > this.windowSize) {
			this.window.shift();
		}
		return this.median();
	}

	/** @returns {number | null} */
	median() {
		if (this.window.length === 0) return null;
		const sorted = [...this.window].sort((a, b) => a - b);
		return sorted[Math.floor((sorted.length - 1) / 2)];
	}

	/** @returns {number} */
	get size() {
		return this.window.length;
	}

	/** @returns {number[]} */
	values() {
		return [...this.window];
	}

	reset() {
		this.window = [];
	}

	/** @param {number} n @returns {number | null} */
	resize(n) {
		checkWindowSize(n);
		this.windowSize = n;
		while (this.window.length > n) {
			this.window.shift();
		}
		return this.median();
	}
}

