import("./src/rolling-median.js").then(({RollingMedian}) => {
  const assert = require("node:assert/strict");
  // R1
  for (const bad of [0, -1, 1.5, NaN, "3", null, undefined, true, Infinity])
    assert.throws(() => new RollingMedian(bad), RangeError);
  // R2
  const m = new RollingMedian(2); m.add(1);
  for (const bad of [NaN, Infinity, -Infinity, "5", 1n, null])
    assert.throws(() => m.add(bad), TypeError);
  assert.deepEqual(m.values(), [1]);
  // R3 even => lower middle
  const e = new RollingMedian(4); e.add(4); e.add(1); e.add(3); e.add(2);
  assert.equal(e.median(), 2); // sorted [1,2,3,4] -> 2
  assert.equal(new RollingMedian(1).median(), null);
  // R4
  const v = e.values(); v.push(99); assert.equal(e.size, 4);
  // R5
  assert.equal(e.reset(), undefined); assert.equal(e.size, 0);
  assert.equal(e.add(7), 7); // windowSize kept at 4
  // R6
  const r = new RollingMedian(3); r.add(1); r.add(2); r.add(3); r.add(4);
  assert.equal(r.resize(1), 4);
  assert.equal(r.resize(10), 4);
  assert.equal(r.add(5), 4.5===undefined ? null : r.median());
  assert.deepEqual(r.values(), [4,5]);
  assert.throws(() => r.resize(0), RangeError);
  assert.throws(() => r.resize(2.5), RangeError);
  assert.equal(r.resize(1), 5);
  console.log("all edge checks pass");
});'
